import json

def run(inp):
    goal = inp.get('goal', '')
    tools = inp.get('tools') or {}
    history = inp.get('history') or []
    remaining = inp.get('remaining') or {}
    state = inp.get('state') or {}
    representation = inp.get('representation')
    model_reply = inp.get('model_reply')

    if not isinstance(representation, dict):
        representation = {}
    repr_dict = dict(representation) if isinstance(representation, dict) else {}

    observed = []
    for entry in history:
        act = entry.get('action') or {}
        obs = entry.get('observation')
        if isinstance(act, dict) and act.get('kind') == 'experiment' and obs is not None:
            observed.append({
                'tool': act.get('tool'),
                'input': act.get('input'),
                'observation': obs,
                'predictions': act.get('predictions') or []
            })

    mapping = {}
    inconsistent = False
    for p in observed:
        try:
            key = json.dumps({'tool': p['tool'], 'input': p['input']}, sort_keys=True)
        except Exception:
            key = repr((p['tool'], p['input']))
        try:
            val = json.dumps(p['observation'], sort_keys=True)
        except Exception:
            val = repr(p['observation'])
        if key in mapping:
            if mapping[key] != val:
                inconsistent = True
        else:
            mapping[key] = val

    hyp_stats = {}
    for p in observed:
        try:
            obs_dump = json.dumps(p['observation'], sort_keys=True)
        except Exception:
            obs_dump = repr(p['observation'])
        for pred in p.get('predictions', []):
            hyp = pred.get('hypothesis')
            outcome = pred.get('outcome')
            try:
                out_dump = json.dumps(outcome, sort_keys=True)
            except Exception:
                out_dump = repr(outcome)
            hit = out_dump == obs_dump
            s = hyp_stats.setdefault(hyp, {'hits':0,'misses':0,'total':0})
            s['total'] += 1
            if hit:
                s['hits'] += 1
            else:
                s['misses'] += 1

    state['observed_points'] = observed
    state['mapping'] = mapping
    state['inconsistent'] = inconsistent
    state['hypothesis_stats'] = hyp_stats

    steps = remaining.get('steps', 0)
    if steps <= 0:
        return {'state': state, 'action': {'kind': 'unresolved', 'reason': 'no steps remaining'}}

    repr_inconsistent = bool(repr_dict.get('inconsistent'))

    if inconsistent and not repr_inconsistent and not state.get('inconsistent_reported'):
        new_repr = dict(repr_dict)
        new_repr['inconsistent'] = True
        new_repr['observed_count'] = len(observed)
        new_repr['evidence_summary'] = [
            {'tool': p['tool'], 'input': p['input'], 'observation': p['observation']}
            for p in observed
        ]
        new_repr['hypothesis_stats'] = hyp_stats
        state['inconsistent_reported'] = True
        return {'state': state, 'action': {'kind': 'revise', 'representation': new_repr, 'reason': 'contradictory observations for same input detected, preserving evidence'}}

    supported = [h for h,s in hyp_stats.items() if s['hits'] >= 2 and s['misses'] == 0]
    falsified = [h for h,s in hyp_stats.items() if s['misses'] >= 2 and s['hits'] == 0]
    cur_supported = repr_dict.get('supported_hypotheses') or []
    cur_falsified = repr_dict.get('falsified_hypotheses') or []
    if set(supported) != set(cur_supported) or set(falsified) != set(cur_falsified):
        new_repr = dict(repr_dict)
        new_repr['hypothesis_stats'] = hyp_stats
        if supported:
            new_repr['supported_hypotheses'] = sorted(supported)
        else:
            new_repr.pop('supported_hypotheses', None)
        if falsified:
            new_repr['falsified_hypotheses'] = sorted(falsified)
        else:
            new_repr.pop('falsified_hypotheses', None)
        return {'state': state, 'action': {'kind': 'revise', 'representation': new_repr, 'reason': 'hypothesis evidence updated from prediction-observation matches'}}

    if model_reply:
        mr = model_reply
        if isinstance(mr, dict) and 'action' in mr and 'kind' not in mr:
            mr = mr.get('action')
        if isinstance(mr, dict):
            kind = mr.get('kind')
            if kind == 'experiment':
                tool = mr.get('tool')
                inp_val = mr.get('input')
                preds = mr.get('predictions')
                if tool in tools and isinstance(preds, list) and len(preds) >= 1:
                    try:
                        key = json.dumps({'tool': tool, 'input': inp_val}, sort_keys=True)
                    except Exception:
                        key = repr((tool, inp_val))
                    if key in mapping:
                        prior_val = mapping[key]
                        pred_outcomes = []
                        for pr in preds:
                            try:
                                pred_outcomes.append(json.dumps(pr.get('outcome'), sort_keys=True))
                            except Exception:
                                pred_outcomes.append(repr(pr.get('outcome')))
                        if prior_val not in pred_outcomes:
                            new_repr = dict(repr_dict)
                            new_repr.setdefault('model_conflict', []).append({'tool': tool, 'input': inp_val})
                            new_repr['hypothesis_stats'] = hyp_stats
                            return {'state': state, 'action': {'kind': 'revise', 'representation': new_repr, 'reason': 'model proposed experiment contradicts prior observation, preserving evidence'}}
                    return {'state': state, 'action': mr}
            if kind == 'answer':
                if inconsistent:
                    new_repr = dict(repr_dict)
                    new_repr['inconsistent'] = True
                    new_repr['hypothesis_stats'] = hyp_stats
                    return {'state': state, 'action': {'kind': 'revise', 'representation': new_repr, 'reason': 'cannot forward answer while contradictory observations exist'}}
                return {'state': state, 'action': mr}
            if kind in ('revise', 'unresolved'):
                return {'state': state, 'action': mr}

    if remaining.get('model_calls', 0) > 0:
        tool_desc = ', '.join(f"{k}: {v}" for k, v in tools.items())
        hyp_summary = '; '.join(f"{h}: {s['hits']}/{s['total']} hits, misses {s['misses']}" for h,s in hyp_stats.items()) or 'none'
        supported_now = [h for h,s in hyp_stats.items() if s['hits'] >= 2 and s['misses'] == 0]
        falsified_now = [h for h,s in hyp_stats.items() if s['misses'] >= 2 and s['hits'] == 0]
        instr = (
            f"Goal: {goal}. Tools: {tool_desc}. Observed points: {len(observed)}. Inconsistent: {inconsistent}. "
            f"Hypothesis stats: {hyp_summary}. Supported: {supported_now}. Falsified: {falsified_now}. "
            "Propose next experiment with kind experiment, valid tool, input and at least one prediction to discriminate hypotheses, or propose answer only if evidence is consistent and sufficient."
        )
        return {'state': state, 'action': {'kind': 'model', 'instruction': instr}}

    return {'state': state, 'action': {'kind': 'unresolved', 'reason': 'budget exhausted without sufficient evidence for a safe answer'}}
